35	
36	const EM_DASH = '—';
37	
38	function factClass(fact: FactText): string {
39	  if (!fact.value) return 'printer-fact-value printer-fact-empty';
40	  return `printer-fact-value printer-fact-${fact.provenance}`;
41	}
42	
43	function factSuffix(fact: FactText): string {
44	  if (!fact.value) return '';
45	  if (fact.provenance === 'assumed') return ' · assumed';
46	  if (fact.provenance === 'changed') return ' · changed';
47	  return '';
48	}
49	
50	function FactRow({ label, fact }: { label: string; fact: FactText }) {
51	  return (
52	    <div className="printer-fact">
53	      <span className="printer-fact-label">{label}</span>
54	      <span className={factClass(fact)}>
55	        {fact.swatch && <span className="printer-swatch" style={{ background: fact.swatch }} aria-hidden="true" />}
56	        {fact.value || EM_DASH}
