15	// -- Numbers and lists --------------------------------------------------------
16	
17	// "0.4", "0.25", "1.0": two decimals, trailing zeros dropped down to one, as
18	// the printer profiles spell nozzle sizes.
19	export function numberText(value: number): string {
20	  let text = value.toFixed(2);
21	  while (text.length > 3 && text.endsWith('0')) text = text.slice(0, -1);
22	  return text;
23	}
24	
25	export function mm(value: number): string {
26	  return `${numberText(value)} mm`;
27	}
28	
29	// "a, b and c"
30	export function listed(items: string[]): string {
31	  return items.map((item, index) => (index === 0 ? '' : index + 1 === items.length ? ' and ' : ', ') + item).join('');
32	}
33	
34	// "0.2, 0.4, 0.6 and 0.8 mm"
35	export function sizesText(nozzles: number[]): string {
36	  return `${listed(nozzles.map(numberText))} mm`;
37	}
38	
39	function spoolName(spool: PrinterSpoolInfo): string {
40	  return spool.name || spool.material;
41	}
42	
43	// "PLA Matte and PETG", or "none"
44	function spoolsText(spools: PrinterSpoolInfo[]): string {
45	  return spools.length === 0 ? 'none' : listed(spools.map(spoolName));
46	}
47	
48	// What a printer has loaded, as one line: "AMS lite · PLA Matte + 3".
49	export function spoolSummary(ams: string, spools: PrinterSpoolInfo[]): string {
50	  if (spools.length === 0) return ams;
51	  const first = spoolName(spools[0]) + (spools.length > 1 ? ` + ${spools.length - 1}` : '');
52	  return ams ? `${ams} · ${first}` : first;
53	}
54	
55	// -- The panel's fixed words --------------------------------------------------
56	
57	export function caption(session: PrinterSessionPayload): string {
58	  return session.mode === 'add' ? 'NEW PRINTER' : 'PRINTER';
59	}
60	
61	// A likely answer, rather than a standing invitation.
62	export function placeholder(session: PrinterSessionPayload): string {
63	  return session.mode === 'add'
64	    ? 'e.g. "bambu a1 mini" or "not sure, the small one"'
65	    : 'e.g. "I put a 0.6 nozzle on it" or "loaded black PETG"';
66	}
67	
68	export const ADD_LABEL = 'Add this printer';
69	export const REJECT_LABEL = 'Not this one';
70	
71	// The panel's own first line, which the model is shown as having said: the
72	// same promise every time the panel opens.
73	export function opening(session: PrinterSessionPayload): string {
74	  if (session.mode === 'change') {
75	    const name = session.context?.printer?.name || session.facts.printer.name || 'this printer';
76	    return `This is the ${name}. Tell me what changed on it, or ask anything about it: nozzle, plate, spools, connection. A photo of the part works too.`;
77	  }
78	  return 'What printer do you have? Say it any way: "bambu a1 mini", "the ender with the touchscreen", "not sure, the small one".';
79	}
