81	// -- The pinned card ----------------------------------------------------------
82	
83	export interface FactText {
84	  value: string; // empty: nobody has said yet
85	  provenance: PrinterFacts['printer']['provenance'];
86	  swatch?: string;
87	}
88	
89	export function factTexts(facts: PrinterFacts): { printer: FactText; nozzle: FactText; plate: FactText; filament: FactText } {
90	  const loaded = facts.filament.spools;
91	  return {
92	    printer: { value: facts.printer.name, provenance: facts.printer.provenance },
93	    nozzle: { value: facts.nozzle.size > 0 ? mm(facts.nozzle.size) : '', provenance: facts.nozzle.provenance },
94	    plate: { value: facts.plate.name, provenance: facts.plate.provenance },
95	    filament: {
96	      value: loaded.length > 0 || facts.filament.ams ? spoolSummary(facts.filament.ams, loaded) : facts.filament.preset,
97	      provenance: facts.filament.provenance,
98	      swatch: loaded[0]?.colour || undefined,
99	    },
100	  };
101	}
