103	// -- The cards in the thread --------------------------------------------------
104	
105	// Under a printer's name: what the printer reported, or its size.
106	export function cardSubline(card: PrinterCardInfo): string {
107	  const device = card.device;
108	  if (!device) return card.buildVolume;
109	  let text = `${mm(device.nozzle)} nozzle`;
110	  if (device.spools.length > 0) text += ` · ${spoolSummary(device.ams, device.spools)}`;
111	  if (device.reported) text += ' · read from the printer just now';
112	  return text;
113	}
114	
115	// The undo row: "Nozzle set to 0.6 mm", "Spools updated", or both.
116	export function undoText(block: PrinterBlock): string {
117	  const parts: string[] = [];
118	  if (block.changed?.nozzle) parts.push(`Nozzle set to ${mm(block.changed.nozzle.after)}`);
119	  if (block.changed?.spools) parts.push(parts.length > 0 ? 'spools updated' : 'Spools updated');
120	  return parts.join(', ');
121	}
122	
123	// The change card's title.
124	export function changeTitle(nozzle: boolean, spools: boolean): string {
125	  return nozzle && spools ? 'Change nozzle and spools' : nozzle ? 'Change nozzle' : 'Change spools';
126	}
